import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.CmaAMB6e.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"learning-by-agent","text":"技能模块化学习系统","tagline":"10 条独立技能线 · 每条自成闭环 · 零基础也能从第一篇走到最后","actions":[{"theme":"brand","text":"我不知道从哪开始","link":"/#你是谁从哪开始"},{"theme":"alt","text":"直接学 Python","link":"/python/"}]},"features":[{"title":"Android (Kotlin)","details":"Jetpack Compose 声明式 UI。28 个概念，从 Hello World 到架构、性能、安全。","link":"/android/","linkText":"进入 Android →"},{"title":"iOS (Swift)","details":"SwiftUI 声明式 UI。28 个概念，覆盖语法、UI、工程化与资深实战。","link":"/ios/","linkText":"进入 iOS →"},{"title":"鸿蒙 (ArkTS)","details":"ArkUI 声明式 UI。28 个概念，含分布式能力与组件化。","link":"/harmony/","linkText":"进入 鸿蒙 →"},{"title":"Python","details":"数据处理、Web 后端与 AI 应用。29 个概念，pandas、FastAPI、LLM 到部署。零基础友好。","link":"/python/","linkText":"进入 Python →"},{"title":"Java","details":"后端开发与 Spring Boot。29 个概念，从语言核心到 JVM、微服务与部署。","link":"/java/","linkText":"进入 Java →"},{"title":"前端","details":"完整前端学习线。29 个概念，从浏览器原理到 React/Vue、架构与性能治理。","link":"/frontend/","linkText":"进入 前端 →"},{"title":"Node.js","details":"运行时原理与后端开发。29 个概念，从事件循环到 NestJS、微服务与部署。","link":"/nodejs/","linkText":"进入 Node.js →"},{"title":"数据库","details":"后端基石。29 个概念，从 SQL 到索引、NoSQL 与分布式数据库。","link":"/database/","linkText":"进入 数据库 →"},{"title":"Linux","details":"服务器运维。29 个概念，从命令到 systemd、Docker 与故障排查。","link":"/linux/","linkText":"进入 Linux →"},{"title":"系统设计","details":"架构师思维。27 个概念，从容量估算到高可用与经典案例。","link":"/system-design/","linkText":"进入 系统设计 →"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1784195062000}'),i={name:"index.md"};function l(n,t,r,s,c,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h2 id="你是谁-从哪开始" tabindex="-1">你是谁？从哪开始 <a class="header-anchor" href="#你是谁-从哪开始" aria-label="Permalink to &quot;你是谁？从哪开始&quot;">​</a></h2><p>不知道先学哪个是正常的——<strong>10 条线是平铺的，但难度和门槛并不相同</strong>。按你的基础对号入座：</p><table tabindex="0"><thead><tr><th>如果你的情况是</th><th>建议从这条线开始</th><th>为什么是它</th></tr></thead><tbody><tr><td><strong>完全 0 基础</strong>，没写过代码</td><td><a href="/learning/python/">Python</a> → <a href="/learning/linux/">Linux</a></td><td>装一个解释器就能跑，不需要 IDE、模拟器、SDK。改一行、跑一次，反馈最快</td></tr><tr><td><strong>会一点编程</strong>，但不熟前端</td><td><a href="/learning/linux/">Linux</a> → <a href="/learning/database/">数据库</a></td><td>不依赖任何前端知识；本站每篇末尾的「前端对照」小节可以直接跳过，不影响主线</td></tr><tr><td><strong>有前端基础</strong>（React / Vue）</td><td><a href="/learning/nodejs/">Node.js</a> 或任意线</td><td>本站就是为这个视角写的，「前端对照」能让你一天入门一门新语言</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">不确定就选 Python</p><p>它是 10 条线里<strong>环境最简单、试错成本最低</strong>的一条。学完 Python 的 01–05，你就已经具备读其他任何一条线的基础了。</p></div><h2 id="推荐学习顺序" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#推荐学习顺序" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><p>如果你打算系统地走完多条线，按<strong>先易后难、先无环境门槛后有环境门槛</strong>排：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Python → Linux → 数据库 → Node.js → 前端 → 系统设计 → Java → Android / iOS / 鸿蒙</span></span>
<span class="line"><span>         └────── 装个解释器/虚拟机就能学 ──────┘        └─ 需要 IDE + SDK + 模拟器 ─┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>顺序</th><th>技能线</th><th>环境门槛</th><th>前置依赖</th></tr></thead><tbody><tr><td>1</td><td>Python</td><td>极低（装 Python）</td><td>无</td></tr><tr><td>2</td><td>Linux</td><td>低（虚拟机或云服务器）</td><td>无</td></tr><tr><td>3</td><td>数据库</td><td>低（Docker 起一个 MySQL）</td><td>无</td></tr><tr><td>4</td><td>Node.js</td><td>低（装 Node）</td><td>懂 JS 更佳</td></tr><tr><td>5</td><td>前端</td><td>低（浏览器 + Node）</td><td>建议先学 Node.js</td></tr><tr><td>6</td><td>系统设计</td><td>无（不写代码，纯设计）</td><td><strong>建议先学数据库 + Linux</strong></td></tr><tr><td>7</td><td>Java</td><td>中（JDK + Maven + IDE）</td><td>建议先学一门语言</td></tr><tr><td>8</td><td>Android / iOS / 鸿蒙</td><td>高（IDE + SDK + 模拟器，10GB 磁盘）</td><td>建议先学一门语言</td></tr></tbody></table><blockquote><p>移动端三条线（Android / iOS / 鸿蒙）结构高度同构，<strong>精通任意一条后，另外两条的学习成本会大幅下降</strong>（概念序列几乎一一对应）。不必三条都走。</p></blockquote><h2 id="系统理念" tabindex="-1">系统理念 <a class="header-anchor" href="#系统理念" aria-label="Permalink to &quot;系统理念&quot;">​</a></h2><p>本系统<strong>不再把多种语言杂糅在一篇文档里对比</strong>，而是把每个技能拆成独立的学习线：</p><ul><li>每个技能有自己的<strong>学习路径、环境搭建、概念教程、笔记、进度</strong></li><li>技能之间互不干扰，可以单独推进任何一个</li><li>每篇概念教程聚焦单一技能，自成闭环</li><li>末尾保留轻量「前端对照」小节，用你已会的 React/Vue/JS 帮助理解新概念</li></ul><h2 id="如何开始" tabindex="-1">如何开始 <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始&quot;">​</a></h2><ol><li>选定一条线后，先读该技能的<strong>环境搭建</strong>，把环境跑通（这步做完再往下走）</li><li>按<strong>学习路径</strong>的概念序列，从 <code>01</code> 顺序学习（每篇开头会写明前置概念和预计耗时）</li><li>边学边在<strong>学习笔记</strong>沉淀速查与踩坑</li><li>每完成一个概念，在<strong>学习进度</strong>更新状态</li><li>每学完一个等级，对照<strong>等级标准 L1-L5</strong> 自检，用 <code>/assess &lt;技能&gt; &lt;等级&gt;</code> 让 AI 考核</li><li>卡住时用 Skill 陪练：<code>/explain &lt;技能&gt; &lt;概念&gt;</code>、<code>/quiz &lt;技能&gt; &lt;概念&gt;</code></li></ol><h2 id="添加新技能" tabindex="-1">添加新技能 <a class="header-anchor" href="#添加新技能" aria-label="Permalink to &quot;添加新技能&quot;">​</a></h2><p>复制 <code>templates/skill-template/</code> 目录到 <code>skills/&lt;新技能名&gt;/</code>，按其中的模板填写即可。然后在 <code>.vitepress/config.mjs</code> 的 <code>sidebar</code> 和 <code>nav</code> 中加入新技能入口。</p><div class="warning custom-block"><p class="custom-block-title">记得接入导航</p><p>新写的页面如果没加进 <code>.vitepress/config.mjs</code> 的 sidebar，它在站上是<strong>访问不到</strong>的（只能通过 GitHub 源码看到）。加完后请顺手确认一次。</p></div><h2 id="陪练-skill" tabindex="-1">陪练 Skill <a class="header-anchor" href="#陪练-skill" aria-label="Permalink to &quot;陪练 Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>/explain &lt;技能&gt; &lt;概念&gt;</code></td><td>以前端视角解释陌生概念</td><td><code>/explain android 协程</code></td></tr><tr><td><code>/practice &lt;技能&gt; &lt;概念&gt;</code></td><td>生成针对性练习任务</td><td><code>/practice ios 状态管理</code></td></tr><tr><td><code>/quiz &lt;技能&gt; &lt;概念&gt;</code></td><td>自测出题并判分</td><td><code>/quiz python 异步编程</code></td></tr><tr><td><code>/track &lt;技能&gt; &lt;动作&gt;</code></td><td>更新该技能进度</td><td><code>/track android 完成 02</code></td></tr><tr><td><code>/assess &lt;技能&gt; &lt;等级&gt;</code></td><td>AI 考核是否达到某等级</td><td><code>/assess android 3</code></td></tr></tbody></table>`,19)])])}const k=d(i,[["render",l]]);export{p as __pageData,k as default};
